second:
\[
\begin{aligned}
\beta+\gamma&=\alpha'&\qquad\alpha&=\frac{\beta'+\gamma'-\alpha'}{2}=\frac{\alpha'+\beta'+\gamma'}{2}-\alpha'\\
\gamma+\alpha&=\beta'&\beta&=\frac{\gamma'+\alpha'-\beta'}{2}\\
\alpha+\beta&=\gamma'&\gamma&=\frac{\alpha'+\beta'-\gamma'}{2}
\end{aligned}
\]
